};

/**
 * @method
 * @name img_189_onclick
 * @description img_189 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_189_onclick = async function(e){
    try {
        await scwin.findIsuDigital(3)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00170.img_189_onclick' }); }
};

/**
 * @method
 * @name img_207_onclick
 * @description img_207 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_207_onclick = async function(e){
    try {
        await scwin.goWrite()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00170.img_207_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_documentWrite
 * @description document Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosurereg.do?method=registerDisclosure",
        ref: "dma_goWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {void}
 * @hidden N
 */
scwin.findCompany = function () {
    const corpSearchURL = '/jldfil00033/jldfil00033.xml?method=loadInitPageForDigital&formcd=' + dma_disclosureVo.get("formCd") + '';
    (Promise.resolve($c.win.openPopup(corpSearchURL, { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "660", type: "pageFramePopup" }, {})).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("corpWin"); this.closed = true; } });
};

/**
 * @method
 * @name findIsuDigital
 * @description find Isu Digital 처리
 * @param {*} dgtype dgtype
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findIsuDigital = async function (dgtype) {
    if (dgtype === '3') {
        if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '') {
            await $c.win.alert('대상회사를 선택하십시요');
            return;
        }
    }
    const txtIsurCd = $c.util.getComponent('ipt_txtisurCd').getValue();
    const txtFormCd = $c.util.getComponent('dma_documentWriteReq').get('formCd');
    const isuSearchURL = '/jldfil00033/jldfil00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup(isuSearchURL, { id: "isuWin", scrollbars: false, resizable: false, width: "600", height: "660", type: "pageFramePopup" }, { method: "loadInitPageIsu", isurCd: txtIsurCd, formCd: txtFormCd }));
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, fssUnqNo) {
    $c.util.getComponent("ipt_txtisurCd").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNo").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtcomNm").setValue(comAbbrv);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('chkPop', 'Y');
    $c.util.getComponent("ipt_txtisuCd_2").setValue('');
    $c.util.getComponent("ipt_txtisuNm").setValue('');
};

/**
 * @method
 * @name setIsuInfo
 * @description set Isu Info 처리
 * @param {String} isurCd isurCd
 * @param {String} repIsuCd repIsuCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} isuKorNm isuKorNm
 * @param {*} isuKorAbbrv isuKorAbbrv
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} returnKey returnKey
 * @returns {void}
 * @hidden N
 */
scwin.setIsuInfo = function (isurCd, repIsuCd, repIsuSrtCd, isuKorNm, isuKorAbbrv, fssUnqNo, returnKey) {
    $c.util.getComponent("ipt_txtisurCd").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNo").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtisuNm").setValue(isuKorAbbrv);
    $c.util.getComponent("ipt_txtisuCd_2").setValue(repIsuCd);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('chkIsuPop', 'Y');
};

/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function () {
    (document.corpForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    await scwin.tx_fn_documentWrite();
};

/**
 * @method
 * @name registerProcess
 * @description register Process 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name registerMessage
 * @description register Message 처리
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMessage = async function (msg) {
    await $c.win.alert(msg);
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function () {
    if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '') {
        await $c.win.alert('대상회사를 선택하십시요');
        return;
    }
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('corpisuBasTpCd', "1");
    scwin.moveStep = true;
    if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtisuNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisuNm').getValue())) === '') {
        await $c.win.alert('대상종목를 선택하십시요');
        return;
    }
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuNm', $c.util.getComponent('ipt_txtisuNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuCd', $c.util.getComponent('ipt_txtisuCd_2').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuNm', $c.util.getComponent('ipt_txtisuNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuCd', $c.util.getComponent('ipt_txtisuCd_2').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('corpisuBasTpCd', "2");
    scwin.moveStep = true;
    if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '') {
        await $c.win.alert('대상회사를 선택하십시요');
        return;
    }
    if (($c.util.getComponent('ipt_txtisuCd_2').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisuCd_2').getValue())) === '' || ($c.util.getComponent('ipt_txtisuNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisuNm').getValue())) === '') {
        await $c.win.alert('대상종목를 선택하십시요');
        return;
    }
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuNm', $c.util.getComponent('ipt_txtisuNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuCd', $c.util.getComponent('ipt_txtisuCd_2').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuNm', $c.util.getComponent('ipt_txtisuNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuCd', $c.util.getComponent('ipt_txtisuCd_2').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('corpisuBasTpCd', "2");
    scwin.moveStep = true;
    (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure';
    (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
    await scwin.tx_fn_goWrite();
};

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
